blocks.text:
\begin{aligned}
\text{Oração com Sujeito} &= [\text{Sujeito}] + [\text{Predicado (Verbo + Complementos/Adjuntos)}] \\
\text{Oração sem Sujeito} &= [\text{Predicado Integral (Toda a Oração)}]
\end{aligned}

structure.mermaidSource:
flowchart TD
  start(["Início: Mapeamento dos Termos"]) --> proc_isolar["Isolar S, V, C e Adv na oração"]
  proc_isolar --> dec_ordem_direta{"A sequência segue a ordem canônica S - V - C - Adv?"}
  dec_ordem_direta -- "Sim" --> res_ordem_direta["Resultado: Ordem Direta Canônica"]
  dec_ordem_direta -- "Não" --> dec_antecipacao{"O Adjunto Adverbial está no início absoluto (antes de S ou V)?"}
  dec_antecipacao -- "Sim" --> res_antecipacao["Resultado: Deslocamento por Antecipação"]
  dec_antecipacao -- "Não" --> dec_intercalacao{"Há termo inserido entre S e V ou entre V e C?"}
  dec_intercalacao -- "Sim" --> res_intercalacao["Resultado: Deslocamento por Intercalação"]
  dec_intercalacao -- "Não" --> res_outra_inversao["Resultado: Outra Inversão Sintática (ex.: V - S)"]

flowchart TD
  start(["Início: Validação do Núcleo do Sujeito"]) --> dec_gatilho{"A assertiva justifica o núcleo por 'ideia principal' ou 'parte mais importante'?"}
  dec_gatilho -- "Sim" --> res_gatilho_errado["Resultado: Gatilho de Rejeição (Item ERRADO)"]
  dec_gatilho -- "Não" --> proc_delimitar["Delimitar o sintagma integral do Sujeito"]
  proc_delimitar --> proc_setas["Aplicar Teste das Setas (identificar termo mais especificado)"]
  proc_setas --> dec_filtro_morfo{"O candidato é substantivo ou pronome/numeral substantivo?"}
  dec_filtro_morfo -- "Não" --> res_satelite["Resultado: Termo Descartado (Satélite / Adjunto Adnominal)"]
  dec_filtro_morfo -- "Sim" --> dec_aposto{"É substantivo específico que individualiza termo genérico antecedente (sem vírgulas)?"}
  dec_aposto -- "Sim" --> res_aposto["Resultado: Núcleo = Termo Genérico (Específico = Aposto Especificativo)"]
  dec_aposto -- "Não" --> res_nucleo_validado["Resultado: Núcleo Formal do Sujeito Validado"]

flowchart TD
  start["Início: Validação do Núcleo do Sujeito"] --> proc_delimitar["Passo 1: Delimitar o sujeito completo da oração"]
  proc_delimitar --> dec_ideia_principal{"A assertiva justifica o núcleo por 'transmitir a ideia principal'?"}
  dec_ideia_principal -- "Sim" --> res_errado_ideia["Julgar item como ERRADO (Critério semântico proibido em prova)"]
  dec_ideia_principal -- "Não" --> proc_teste_setas["Passo 2: Aplicar o Teste das Setas (Mapear especificadores)"]
  proc_teste_setas --> dec_mais_especificado{"O termo é o polo de atração sobre o qual recaem os modificadores?"}
  dec_mais_especificado -- "Não" --> res_termo_modificador["Termo NÃO é núcleo (Trata-se de adjunto ou determinante)"]
  dec_mais_especificado -- "Sim" --> dec_filtro_morfo{"Passo 3: O termo é substantivo, pronome substantivo ou numeral substantivo?"}
  dec_filtro_morfo -- "Não (é adjetivo/outro)" --> res_adjetivo_excluido["Descarte morfológico: Adjetivo não pode compor o núcleo do sujeito"]
  dec_filtro_morfo -- "Sim" --> res_nucleo_validado["Núcleo do Sujeito Formalmente VALIDADO"]
